export const getTranscribeAudioUrl = () => {




  return `/api/audio/transcribe`
}

/**
 * @summary Transcribe an audio recording or uploaded file (webm, mp3, m4a, wav, ogg) to text
 */
export const transcribeAudio = async (audioUpload: AudioUpload, options?: Parameters<typeof customFetch>[1]): Promise<Transcription> => {
    const formData = new FormData();
formData.append(`file`, audioUpload.file);
if(audioUpload.language !== undefined) {
 formData.append(`language`, audioUpload.language);
 }
if(audioUpload.store !== undefined) {
 formData.append(`store`, audioUpload.store);
 }

  return customFetch<Transcription>(getTranscribeAudioUrl(),
  {
    ...options,
    method: 'POST'
    ,
    body: formData
  }
);}





